--
-- Структура таблицы `donations`
--

CREATE TABLE `donations` (
  `id` int(11) NOT NULL,
  `acc_id` int(11) NOT NULL,
  `amount` int(11) NOT NULL,
  `time` varchar(16) NOT NULL,
  `date` varchar(16) NOT NULL,
  `activated` int(11) NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

-- --------------------------------------------------------

--
-- Структура таблицы `dragy`
--

CREATE TABLE `dragy` (
  `id` int(11) NOT NULL,
  `owner` int(11) NOT NULL DEFAULT -1,
  `veh_id` int(11) NOT NULL,
  `veh_srv` int(11) NOT NULL DEFAULT -1,
  `s100` float NOT NULL DEFAULT 0,
  `s200` float NOT NULL DEFAULT 0,
  `s300` float NOT NULL DEFAULT 0,
  `s400` float NOT NULL DEFAULT 0,
  `s100_200` float NOT NULL DEFAULT 0,
  `s200_300` float NOT NULL DEFAULT 0,
  `s300_400` float NOT NULL DEFAULT 0,
  `date` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Структура таблицы `event_dacha_players`
--

CREATE TABLE `event_dacha_players` (
  `account_id` int(11) NOT NULL,
  `level` int(11) NOT NULL DEFAULT 0,
  `experience` int(11) NOT NULL DEFAULT 0,
  `created_at` int(11) NOT NULL DEFAULT 0,
  `updated_at` int(11) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=cp1251 COLLATE=cp1251_general_ci;

-- --------------------------------------------------------

--
-- Структура таблицы `family`
--

CREATE TABLE `family` (
  `id` int(11) NOT NULL,
  `name` varchar(64) NOT NULL DEFAULT '',
  `u_id` int(11) NOT NULL DEFAULT 0,
  `time` int(11) NOT NULL DEFAULT 0,
  `color` int(11) NOT NULL DEFAULT -1,
  `level` int(11) NOT NULL DEFAULT 1,
  `score` int(11) NOT NULL DEFAULT 1,
  `exp` int(11) NOT NULL DEFAULT 0,
  `rank1` varchar(32) NOT NULL DEFAULT 'Новичок',
  `rank2` varchar(32) NOT NULL DEFAULT 'Участник',
  `rank3` varchar(32) NOT NULL DEFAULT 'Опытный',
  `rank4` varchar(32) NOT NULL DEFAULT 'Старший',
  `rank5` varchar(32) NOT NULL DEFAULT 'Проверенный',
  `rank6` varchar(32) NOT NULL DEFAULT 'Ветеран',
  `rank7` varchar(32) NOT NULL DEFAULT 'Заместитель',
  `rank8` varchar(32) NOT NULL DEFAULT 'Совладелец',
  `rank9` varchar(32) NOT NULL DEFAULT 'Заместитель лидера',
  `rank10` varchar(32) NOT NULL DEFAULT 'Лидер',
  `money` int(11) NOT NULL DEFAULT 0,
  `drugs` int(11) NOT NULL DEFAULT 0,
  `tree` int(11) NOT NULL DEFAULT 0,
  `metal` int(11) NOT NULL DEFAULT 0,
  `ammo` int(11) NOT NULL DEFAULT 0,
  `house_id` int(11) NOT NULL DEFAULT -1,
  `pos_x` float NOT NULL DEFAULT 0,
  `pos_y` float NOT NULL DEFAULT 0,
  `pos_z` float NOT NULL DEFAULT 0,
  `pos_fa` float NOT NULL DEFAULT 0,
  `inter` int(11) NOT NULL DEFAULT 0,
  `world` int(11) NOT NULL DEFAULT 0,
  `r_TakeMoney` int(11) NOT NULL DEFAULT 10,
  `r_TakeDrugs` int(11) NOT NULL DEFAULT 10,
  `r_TakeMetall` int(11) NOT NULL DEFAULT 10,
  `r_TakeAmmo` int(11) NOT NULL DEFAULT 10,
  `r_Inv` int(11) NOT NULL DEFAULT 9,
  `r_UnInv` int(11) NOT NULL DEFAULT 9,
  `r_Mute` int(11) NOT NULL DEFAULT 9,
